#[test]
fn prepared_source_repeated_live_target_edits_stream_without_stale_revisions() {
    struct Repeated { object: Mobject, target: Mobject, stage: u32 }
    impl LiveContinuation for Repeated {
        type Error = String;
        fn resume(&mut self, live: &mut LiveSession<'_>) -> Result<ContinuationStep, String> {
            let stage = self.stage; self.stage += 1;
            if stage == 0 { return live.wait_segment(1.0).map(ContinuationStep::Await).map_err(|e|e.to_string()); }
            if stage > 48 { return Ok(ContinuationStep::Finished); }
            // Detached edits still belong to the same publication owner once
            // live execution exists; bypassing it invalidates the next activation.
            live.set_translation(&self.target, if stage.is_multiple_of(2) { 1.0 } else { -1.0 }, 0.0).map_err(|e|e.to_string())?;
            live.declare_and_activate_transform_to(&self.object, &self.target,
                AnimationOptions::new().run_time(0.05).rate_func(noon_core::RateFunction::Linear))
                .map(ContinuationStep::Await).map_err(|e|e.to_string())
        }
    }
    let mut scene=Scene::new(); let object=scene.circle(0.8).unwrap(); scene.add(&object).unwrap();
    let target=object.target_editor().unwrap();
    let mut source=scene.into_live_program(Repeated{object,target,stage:0}).unwrap()
        .into_prepared_source(ReplayLimits{revisions:1024,payloads:16384}).unwrap();
    assert!(matches!(source.step().unwrap(),PrefixPreparation::Progress));
    let mut reader=match source.step().unwrap(){PrefixPreparation::Bootstrap(r)=>*r,other=>panic!("{other:?}")};
    let baseline=reader.frame().clone();let publication=reader.publication_context();
    let mut transitions=0;let mut deliveries=0;
    while source.status()==PreparedSourceStatus::Preparing {
        transitions+=1; assert!(transitions<=97);
        match source.step().unwrap(){
            PrefixPreparation::Progress=>{},
            PrefixPreparation::Batch(batch)=>{
                deliveries+=1;reader.reserve_object_capacity(batch.required_object_capacity()).unwrap();
                reader.preflight_append(&batch).unwrap();reader.append(*batch).unwrap();
                assert_eq!(reader.frame(),&baseline);assert_eq!(reader.publication_context(),publication);
            },
            other=>panic!("{other:?}"),
        }
    }
    assert_eq!(transitions,97);assert_eq!(deliveries,49);drop(source);
    let end=reader.end_time().unwrap();assert!((end-3.4).abs()<1e-9);
    reader.advance_to(end).unwrap();assert_eq!(reader.frame().objects[0].transform.translation,Vec2::new(1.0,0.0));
    reader.seek(1.025).unwrap();assert!((reader.frame().objects[0].transform.translation.x+0.5).abs()<1e-5);
    reader.seek(0.0).unwrap();assert_eq!(reader.frame(),&baseline);
}

